O=Path(__file__).resolve().parent
sources=[dict(regimen='00238',version='6',pages=8,review_date='2030-01-27',url='https://healthservice.hse.ie/documents/6336/238_v6_Aflibercept_and_FOLFIRI.pdf'),dict(regimen='00791',version='2',pages=9,review_date='2030-11-18',url='https://healthservice.hse.ie/documents/6416/791_v2_Bevacizumab_5mgkg_5FU.pdf')]
for s in sources:
 s.update(checked_date='2026-11-04',pdf_sha256=hashlib.sha256((O/(s['regimen']+'.pdf')).read_bytes()).hexdigest(),text_sha256=hashlib.sha256((O/(s['regimen']+'.txt')).read_bytes()).hexdigest())
issues=[]
def issue(id,c,severity,before,after,pages,tests):issues.append(dict(id=id,regimen=c,severity=severity,before=before,correction=after,source_pages=pages,acceptance_case_families=tests,status='source_reconciled_software_checked_independent_review_pending'))
issue('238-BORROWED-FOLFIRI','00238','high','Standard FOLFIRI00227 dose-level, timed ANC/platelet stop and grade-based toxicity rules had been copied into aflibercept/FOLFIRI; governance even named NCCP00227.','Removed borrowed dose levels and timed stops. Rebuilt from own Table2 recurrence/percentage pathways; current ANC<1.5 or platelets<75 holds independently of duration.',[4,5],['ANC independent hold','no borrowed time-stop','no borrowed levels','platelets independent hold'])
issue('238-FN-RECURRENCE','00238','high','Grade4 neutropenia with fever used generic level reductions rather than recurrence-specific component decisions.','First FN/sepsis: irinotecan15–20% selected by consultant; second additionally5-FU bolus+infusion20% while maintaining reduced irinotecan; third consider aflibercept2mg/kg/G-CSF. Recovery/current-dose history are never assumed; no numeric range midpoint.',[4],['FN occurrence','FN range/history not quantified','legacy FN requires occurrence','active FN hold dominates future change'])
issue('238-RENAL-CONFLICT','00238','high','Severe renal dosing selected a numeric amount from a range and did not expose the renal-exclusion conflict.','Table1 CrCl<10/dialysis50–66% starting irinotecan range requires consultant choice; page2 renal-impairment exclusion conflicts with the renal dosing table. Block numeric fallback. A renal impairment flag exposes the broader eligibility conflict.',[2,3],['renal source conflict','renal range not quantified','renal exclusion conflict'])
issue('238-HEPATIC-BOUNDARIES','00238','high','Strict bilirubin/AST boundaries and initial-versus-current dose history were insufficiently separated.','Irinotecan bilirubin>3ULN contraindicated. FU bilirubin>85 OR AST>180 contraindicated; exact85/180 unresolved. Both values needed for full-dose band. Moderate/severe initial reductions remain consultant decisions reconciled with absolute contraindications and dose history.',[3,4],['bilirubin boundary','AST boundary','paired liver values below thresholds','hepatic history not assumed'])
issue('238-AFLIBERCEPT-RECURRENCE','00238','high','Proteinuria and hypertension lacked source-specific recurrence/recovery and component-specific vascular stops.','Aflibercept holds at protein≥2g/24h (not bevacizumab threshold); second occurrence requires recovery<2 and permanent2mg/kg reduction. Hypertension recurrent significant/severe requires control and2mg/kg. Persistent uncontrolled HTN/crisis, severe bleed, GI perforation/fistula, ATE, grade4VTE, nephrotic/TMA, intervention-requiring wound healing and PRES stop aflibercept only.',[5],['protein hold','second protein recovery','HTN recurrence unknown control','aflibercept stop','component scope'])
issue('238-FOLFIRI-TOXICITY','00238','high','Severe diarrhoea/stomatitis followed generic borrowed level/time algorithms.','First severe diarrhoea irinotecan15–20%; second add FU20%; severe persistence despite both reductions stops FOLFIRI, not automatically aflibercept. Severe stomatitis/PPE FU20%. Source term severe is explicit; current/recovery and actual dose history required; no automatic level-based substitution.',[5],['severe diarrhoea recurrence','diarrhoea no midpoint','stomatitis no automatic reference dose','persistent diarrhoea stops FOLFIRI only'])
issue('238-INFUSION-SURGERY','00238','high','Infusion severity and elective-surgery timing were not distinct.','Mild/moderate aflibercept reaction suspends infusion until resolved; severe reaction stops whole combination. Suspend aflibercept at least4weeks before elective surgery; intervention-requiring wound complication follows permanent stop.',[3,4,5],['mild infusion reaction','severe reaction stops whole combination','preoperative hold'])
issue('238-SUPPORT-SCHEDULE','00238','moderate','Protocol supportive-care map incorrectly labelled aflibercept/FOLFIRI low emetogenic risk; schedule drug ordering insufficiently distinguished.','Corrected to moderate due irinotecan. Aflibercept first60min, irinotecan90min/FA2h, thenFUbolus and46h pump, q14d. Source atropine, delayed-diarrhoea and bolus ice-chip context preserved.',[1,6,7],['moderate emetic risk','14-day/46-hour schedule'])
issue('791-ORGAN-FUNCTION','00791','high','Five OF590 organ rules imported bilirubin85/AST180 cutoffs and one-third/half dose reductions from other FU regimens.','Replaced with current v2Table3: renal/dialysis no adjustment expected; mild/moderate hepatic without renal impairment no adjustment expected; severe hepatic not recommended. Combined renal/hepatic impairment or unresolved renal status requires review; no imported absolute cutoffs.',[4],['hepatic mild renal none','hepatic moderate renal none','combined hepatic','severe hepatic not recommended','no borrowed liver contraindication'])
issue('791-FU-DOSELEVELS','00791','high','No regimen-specific complete dose-level/recovery model.','FUbolus400→320→240→stop; infusion2400→2000→1600→stop; folinic400 until associated bolus omitted. Each current component level required; nonstandard actual doses review. Further reduction below−2 explicitly stops the exhausted component, including associated folinic acid for bolus.',[3,4,6],['nadir one level','exact component doses','uses actual previous levels','nonstandard history blocks calculation'])
issue('791-COUNTS-RECOVERY','00791','high','Generic blood-count rules omitted source duration, nadir and distinct platelet maintenance behaviour.','ANC<1 hold, persistent at2weeks stop; lowestANC<1 reduces1level after recovery within2weeks. Platelet<75 hold; ALL nadir bands maintain dose; persistent at4weeks stop. Two-to-four-week source gap requires review. Counts/recovery/time/history missing blocks calculated restart.',[4],['ANC two-week stop','platelet two-week hold','platelet three-week gap','platelet four-week stop','platelet nadir maintain','missing prevents numeric restart'])
issue('791-GI-GRADING','00791','high','Generic toxicity grade rules did not distinguish source definitions, highest grade, current recovery or required reductions.','Current≥G2 diarrhoea/stomatitis independently holds; persistent2weeks stops FU pathway. Recovered diarrhoeaG3/4 and stomatitisG3 reduce1level; stomatitisG4 reduces2. Table6 older source symptom grades are explicitly labelled and preserved, not silently rewritten as CTCAE5. Missing recovery/timing/source-grade/current-dose context blocks numeric restart.',[6],['independent hold','two-week persistence','with recovery','no numeric when missing','exact source grading'])
issue('791-PROTEINURIA','00791','high','Generic proteinuria grade failed source dipstick/concentration/24-hour distinctions and exact2g threshold.','Dipstick2+/3+ or protein≥1g/L permits scheduled administration from this domain and collection within3days before next dose; dipstick4+holds;24h≤2 meets domain,>2–4holds,>4stops. More restrictive concurrent results govern; no bevacizumab reduction.',[5],['protein ≤2','protein hold','protein stop','dipstick','quantitative stop overrides dipstick collection'])
issue('791-BP-VASCULAR','00791','high','Generic numeric BP and mixed bleed/thrombosis/fistula fields implied broader hold/stop actions than source supports.','Explicit uncontrolled/symptomatic day1 hypertension holds;G2–3 treat/consider interruption;G4/persistentG3 stops. Numeric>150/100 contextual persistence/treatment definition and AND/OR ambiguity are exposed. TE/grade4fistula,GIperforation,G4thrombosis,≥G3bleed stop bev only. Combined legacy fields request specificity.',[2,5],['HTN explicit day1 hold','HTN stop','numeric BP needs clinical context','specific stop component','broad legacy field requires specificity'])
issue('791-CONSENT-EVIDENCE','00791','moderate','Unlicensed Irish bevacizumab regimen status and whole-strategy trial limitations were not explicit.','Baseline review checks information/consent/local governance. NCCP source-cited study is an induction-maintenance-reintroduction strategy; no isolated00791 comparative survival number is assigned. Patient and root KB agents notified; primary trial evidence provided.',[8,9],['baseline unlicensed consent'])
summary=json.loads((O/'source-case-results.json').read_text());old=json.loads((O/'source-case-results-baseline.json').read_text())
out=dict(release='0.84.33',baseline_commit='7963400d502f0407d3fa3a733d774db2d3f07ef6',checked_date='2026-11-04',catalogue_url='https://healthservice.hse.ie/staff/information-healthcare-workers/nccp/gastro-intestinal-sact-regimens/',sources=sources,findings=issues,validation=dict(current_cases_passed=summary['passed'],current_cases_total=summary['total'],current_failed=summary['failed'],before_snapshot_passed=old['passed'],before_snapshot_failed=old['failed'],before_snapshot_note='Expected failing acceptance comparison; includes absent new pathways/fields and source-map assertions, not252 distinct clinical defects.',consultant_reviewed=False,oncology_pharmacy_reviewed=False,clinical_use_authorised=False),pending_interpretations=['00238 renal exclusion versus renal dosing table; no automated numeric choice.','00238 count recovery wording uses OR; implementation holds if either current count is below threshold and requires assessment of both before restart.','00238 renal50–66% and irinotecan15–20% ranges require consultant choice; UGT1A1-specific dose not specified in NCCP00238.','00238 strict hepatic exact85/180 boundaries remain unassigned.','00791 platelet recovery2weeks versus discontinuation4weeks gap requires review.','00791 source-table GI toxicity grading differs from CTCAE5.0; explicit reconciliation required.','00791 BP >150/100 source does not explicitly state AND/OR logic; numeric values route to clinical assessment, explicit uncontrolled/symptomatic status drives hold.'],trial_evidence_file='trial-evidence.json')
(O/'findings.json').write_text(json.dumps(out,indent=2,ensure_ascii=False)+'\n')
